head.b:skin:
/* <Group description="Warna SaePaper" selector="body"><Variable name="accentColor" description="Warna utama" type="color" default="#f01e32" value="#f01e32"/><Variable name="secondaryColor" description="Warna sekunder" type="color" default="#600c14" value="#600c14"/></Group> */.sp-layout-wrap{display:contents}
/* SaePaper 1.0.1 | Layout measured against Zon Plus, 27 October 2026. */
:root{--accent:$(accentColor);--secondary:$(secondaryColor);--ink:#222;--body:#484848;--line:#e7e7e7;--wrap:1366px;--heading:'Roboto Slab',Georgia,serif;--text:Roboto,Arial,sans-serif}
*{box-sizing:border-box}body{margin:0;color:var(--body);background:#fff;font:400 15px/1.533 var(--text)}a{color:inherit;text-decoration:none}a:hover{color:var(--accent)}button,input{font:inherit}button,a,input{touch-action:manipulation}button{cursor:pointer}button:disabled{cursor:default}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #1596d2;outline-offset:3px}img{max-width:100%;height:auto;vertical-align:middle}h1,h2,h3,h4{margin:0 0 20px;color:var(--ink);font-family:var(--heading);font-weight:500;line-height:1.4}p{margin:0 0 20px}button{border:0;background:none;color:inherit}[hidden]{display:none!important}.wrap{width:94%;max-width:var(--wrap);margin:auto}.widget{margin:0}.section{min-width:0}.skip-link{position:fixed;top:-100px;left:20px;z-index:2000;padding:12px;background:white}.skip-link:focus{top:10px}.sp-config{display:none}.feed-status{padding:35px 15px;text-align:center;color:#666;background:#f7f7f7;min-height:120px}.feed-retry{border:1px solid var(--line);padding:8px 18px;margin-top:10px}.feed-status:empty{display:none}.feed-items{min-width:0}.news-card{min-width:0}.thumb{display:block;overflow:hidden;background:#eee;aspect-ratio:1.445}.thumb img{width:100%;height:100%;object-fit:cover;transition:transform .35s}.thumb:hover img{transform:scale(1.035)}.card-title{font-size:20px;line-height:1.39;margin:10px 0 9px;overflow-wrap:anywhere}.meta{font:400 12px/1.6 var(--text);color:#767676;display:block;margin:0 0 15px}.meta:before{content:'\25A6';margin-right:5px}.categories{display:flex;flex-wrap:wrap;gap:4px 10px;margin-top:13px;font:500 12px/1.5 var(--text);text-transform:uppercase}.categories a{color:color-mix(in srgb,var(--cat,#f01e32) 65%,#333);display:inline-flex;align-items:center;gap:4px}.categories a:before{content:'';display:inline-block;flex:none;width:10px;height:10px;border-radius:50%;background:var(--cat,#f01e32);box-shadow:3px 0 0 0 color-mix(in srgb,var(--cat,#f01e32) 55%,white)}.excerpt{margin: