.breaking{height:40px;background:#8f0a16;color:white;overflow:hidden}.breaking>.wrap{display:flex;height:40px}.breaking-label{flex:none;position:relative;padding:10px 25px 10px 10px;background:var(--secondary);font:500 12px/20px var(--heading);text-transform:uppercase;z-index:1}.breaking-label:after{content:'';position:absolute;right:-18px;top:0;border-top:20px solid transparent;border-bottom:20px solid transparent;border-left:18px solid var(--secondary)}.ticker-feed{min-width:0;flex:1;overflow:hidden}.ticker-feed .feed-status{min-height:40px;height:40px;padding:8px;color:white;background:transparent}.ticker-feed .feed-items{display:flex;white-space:nowrap;width:max-content;animation:ticker 40s linear infinite;gap:22px}.ticker-feed:hover .feed-items,.ticker-feed:focus-within .feed-items{animation-play-state:paused}.ticker-item{display:flex;align-items:center;gap:14px;font:500 14px/1.4 var(--heading);height:40px}.ticker-item img{width:56px;height:40px;object-fit:cover}.ticker-item:hover{color:white;text-decoration:underline}@keyframes ticker{from{transform:translateX(30vw)}to{transform:translateX(-55%)}}
.topbar{background:#f4f4f4;font-size:12px;min-height:40px}.topbar>.wrap{display:flex;align-items:center;gap:16px;min-height:40px}.top-details{display:flex;align-items:center;gap:16px;flex:1;flex-wrap:wrap}.top-links{display:flex;gap:15px}.social-links{display:flex;flex-wrap:wrap;gap:18px;align-items:center;font-weight:700;font-size:14px}.live-link{align-self:stretch;display:flex;align-items:center;padding:0 12px;background:var(--accent);color:white}.masthead>.wrap{display:flex;justify-content:space-between;align-items:center;padding:20px 0;gap:35px;min-height:130px}.brand{display:inline-flex;align-items:center;line-height:1}.brand-initial{font:italic 700 82px/.9 Georgia,serif;color:var(--secondary);letter-spacing:-13px;padding-right:15px;transform:rotate(-8deg)}.brand-name{font:700 32px/1 var(--text);letter-spacing:-1.2px;color:#171717}.brand-name em{font-style:normal;color:var(--accent)}.brand-tagline{font-size:10px;letter-spacing:2px;display:block;margin-top:7px;color:#555}.brand-image{max-height:85px;max-width:320px;width:auto}.header-ad{width:768px;max-width:60%}.ad-placeholder{display:flex;align-items:center;justify-content:center;text-align:center;position:relative;max-width:100%;overflow:hidden;color:#8d7b7d;border:1px solid #e9d7d9;background:repeating-linear-gradient(135deg,#f2e8ea 0,#f2e8ea 22px,#f7f0f1 22px,#f7f0f1 44px);font-family:var(--heading)}.ad-placeholder strong{font-size:27px;letter-spacing:5px;font-weight:400}.ad-placeholder small{position:absolute;bottom:6px;left:10px;font:10px var(--text);letter-spacing:1px}.ad-wide{aspect-ratio:768/90}.ad-banner{aspect-ratio:950/240}.ad-tall{height:600px;width:300px;max-width:100%;margin:0}.ad-tall strong{font-size:23px;letter-spacing:2px}.ad-square{width:300px;aspect-ratio:1}.ad-caption{font-size:13px;font-style:italic;color:#8b8b8b;margin:8px 0 0}.ad-slot{margin-bottom:35px}.ad-slot .widget-content>img,.ad-slot iframe{max-width:100%}.header-ad .ad-slot{margin:0}
.nav-shell{background:var(--accent);color:#fff;position:sticky;top:0;z-index:100}.nav-inner{display:flex;align-items:center;min-height:50px;position:relative}.home-link{display:grid;place-items:center;width:50px;height:50px;background:var(--secondary);flex:none}.home-link svg{width:28px;height:28px;fill:white}.main-menu{display:flex;flex:1;min-width:0}.main-menu .widget-content>ul{display:flex;align-items:center;list-style:none;padding:0;margin:0}.main-menu li{position:relative;list-style:none}.main-menu a,.main-menu summary{display:block;padding:0 11px;font-size:14px;font-weight:500;line-height:50px;text-transform:uppercase;white-space:nowrap;color:white;cursor:pointer}.main-menu a:hover,.main-menu summary:hover{background:var(--secondary)}.main-menu summary{list-style:none}.main-menu summary:after{content:'\2304';margin-left:8px}.main-menu details>ul{position:absolute;top:50px;left:0;padding:0;margin:0;min-width:190px;background:#fff;box-shadow:0 6px 20px #0002}.main-menu details>ul a{color:#444;text-transform:none;line-height:43px}.main-menu details>ul a:hover{color:white}.nav-actions{display:flex;align-items:center;margin-left:auto}.icon-button{width:45px;min-height:45px;display:grid;place-items:center;color:white}.icon-button svg{width:23px;height:23px;fill:none;stroke:currentColor;stroke-width:2}.menu-toggle{display:none;margin-right:auto}.search-panel{position:absolute;right:45px;top:55px;background:white;padding:20px;box-shadow:0 2px 12px #0003;width:330px;max-width:calc(100vw - 24px);color:#444}.search-panel form{display:flex}.search-panel input{width:100%;min-width:0;padding:10px;border:1px solid #ddd;background:#f7f7f7}.search-panel button{background:var(--accent);color:white;padding:8px 12px}.search-panel #searchClose{background:#eee;color:#333;margin-left:5px}.side-drawer{border:0;margin:0 0 0 auto;padding:25px;width:330px;max-width:90vw;height:100dvh;max-height:100dvh;box-shadow:-10px 0 30px #0002}.side-drawer::backdrop{background:#0009}.drawer-close{d