.hero .feed-items,.highlights .feed-items,.sports .feed-items{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}.hero .feed-items::-webkit-scrollbar,.highlights .feed-items::-webkit-scrollbar,.sports .feed-items::-webkit-scrollbar{display:none}.hero .news-card{flex:0 0 25%;height:400px;border:1px solid #ffffff55;position:relative;scroll-snap-align:start}.is-overlay .thumb{position:absolute;inset:0;aspect-ratio:auto}.is-overlay .thumb:after{content:'';position:absolute;inset:0;background:linear-gradient(transparent 25%,#000c)}.is-overlay .card-copy{position:absolute;left:20px;right:20px;bottom:20px;pointer-events:none}.is-overlay .card-copy a{pointer-events:auto}.is-overlay .card-title{color:white}.is-overlay .categories a{color:white;font-size:10px}.is-overlay .meta{color:#fff;font-size:10px;text-transform:uppercase;margin-bottom:0}.hero .carousel-prev,.hero .carousel-next{opacity:0;transition:opacity .2s}.hero:hover .carousel-prev,.hero:hover .carousel-next,.hero:focus-within .carousel-prev,.hero:focus-within .carousel-next{opacity:1}.carousel-prev,.carousel-next{position:absolute;z-index:2;top:50%;background:var(--accent);color:white;width:30px;height:44px;font-size:28px;line-height:1}.carousel-prev{left:0}.carousel-next{right:0}.carousel-dots{position:absolute;right:4%;bottom:22px;display:flex;gap:2px;z-index:3}.carousel-dots button{width:18px;height:25px;padding:5px;background:none}.carousel-dots button:after{content:'';display:block;width:9px;height:9px;border-radius:50%;background:#ffffff99}.carousel-dots button[aria-current=true]:after{background:var(--accent)}.hero.sp-feed{margin-bottom:0}.highlights-band{background:#200205;padding:40px 0;color:white;margin:0 0 30px}.highlights.sp-feed{margin:0}.highlight-heading{margin:0 30px 30px;border-bottom:2px solid #ffffff50;text-align:center;font-size:20px;color:#fff;position:relative;padding-bottom:14px}.highlight-heading:after{content:'';position:absolute;left:50%;bottom:-10px;border-to