.site-footer{background:#fbfbfb;border-top:1px solid #eee}.footer-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:30px;padding:40px 0 50px}.footer-grid h2{font-size:18px;margin-bottom:35px}.footer-grid .brand{margin:10px 0 35px}.footer-grid .brand-initial{font-size:90px}.footer-grid .brand-name{font-size:32px}.footer-grid p{font-size:14px}.gallery .feed-items{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.gallery .thumb{aspect-ratio:1.45}.footer-links{display:flex;flex-direction:column;gap:13px;font-size:14px}.footer-grid address{font-size:14px;font-style:normal;line-height:2.2}.footer-bottom{background:#f4f4f4;font-size:12px}.footer-menu{display:flex;justify-content:center;flex-wrap:wrap;gap:10px 20px;padding:22px 0;border-bottom:1px solid #ddd}.copyright-row{display:flex;justify-content:space-between;align-items:center;gap:25px;padding:20px 0}.copyright-row p{margin:0;color:#777}.back-top{position:fixed;right:40px;bottom:40px;background:var(--accent);color:white;width:45px;height:45px;z-index:99;font-size:12px;opacity:0;pointer-events:none}.back-top.is-visible{opacity:1;pointer-events:auto}
