/* SaePaper 1.1.0 — SaeKompi header structure with SaePaper colours. */
.section{margin:0}
.widget{font:inherit}
.portal-header .main-menu li{padding:0}
svg.mdi{display:inline-block;width:1em;height:1em;fill:currentColor;stroke:none;vertical-align:-.15em;flex:none}
.icon-button svg.mdi,.search-panel svg.mdi,.header-search svg.mdi{width:23px;height:23px;fill:currentColor;stroke:none;stroke-width:0}
.home-link svg.mdi{width:25px;height:25px;fill:currentColor;stroke:none}
.meta:before,.main-menu summary:after{content:none}
.categories a:before{content:none}
.categories .category-mark{width:14px;height:14px;color:var(--cat,var(--accent));margin-left:-2px;margin-right:-3px}
.meta>.mdi{width:14px;height:14px;margin-right:5px;vertical-align:-2px}
.social-links a{display:inline-flex;align-items:center;justify-content:center;font-size:18px!important;min-width:18px;min-height:24px}
.social-links .mdi{width:18px;height:18px}
.block-heading .mdi{width:18px;height:18px;vertical-align:-4px}
.carousel-prev,.carousel-next{display:grid;place-items:center;font-size:25px}
.carousel-prev .mdi,.carousel-next .mdi{width:25px;height:25px}
.drawer-close,.back-top{display:grid;place-items:center}
.drawer-close .mdi,.back-top .mdi{width:24px;height:24px}
.breaking-label>.mdi{margin-right:6px;width:16px;height:16px;vertical-align:-3px}
.live-link>.mdi{margin-right:6px;width:16px;height:16px}
.post-navigation a,.pager a,.read-more{display:inline-flex;align-items:center;gap:6px}
.post-navigation a .mdi,.pager a .mdi,.read-more .mdi{flex:none;width:18px;height:18px}
.portal-header{position:sticky;top:-102px;z-index:100;background:#fff;box-shadow:0 2px 9px #0000000a}
.portal-header .masthead{background:#fff;border-bottom:1px solid var(--line)}
.portal-header .masthead>.wrap{height:102px;min-height:102px;padding:12px 0;display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:30px}
.portal-header .masthead #spBrand{flex:0 0 auto;max-width:300px}
.portal-header .masthead #spBrand a{display:inline-block}
.portal-header .brand-initial{font-size:72px;letter-spacing:-11px;padding-right:13px}
.portal-header .brand-name{font-size:31px}
.portal-header .brand-tagline{font-size:9px;letter-spacing:1.7px}
.portal-header .brand-image{max-width:280px;max-height:74px;object-fit:contain}
.header-tools{display:flex;align-items:center;justify-content:flex-end;gap:14px;min-width:0;margin-left:auto}
.header-search{width:350px;max-width:31vw;min-width:190px}
.header-search{display:flex;align-items:center;border:1px solid #dedede;border-radius:5px;background:#f7f7f7;overflow:hidden}
.header-search input{width:100%;min-width:0;border:0;outline-offset:-3px;background:transparent;padding:13px 14px;color:var(--ink);font-size:13px;line-height:20px}
.header-search button{display:grid;place-items:center;flex:none;width:45px;height:46px;color:var(--accent)}
.header-search button:hover{background:#ececec}
.quick-read-link{display:inline-flex;align-items:center;gap:7px;font-size:13px;font-weight:500;white-space:nowrap;color:var(--accent);padding:10px 2px}
.quick-read-link .mdi{width:19px;height:19px}
.portal-header .icon-button{width:48px;height:48px;min-height:48px;flex:none;color:#333;border-radius:50%;transition:background .15s}
.portal-header .icon-button:hover{background:#f1f1f1;color:var(--accent)}
.portal-header .menu-toggle,.portal-header .mobile-search{display:none;margin:0}
.theme-mode-toggle .mode-sun{display:none}
.theme-mode-toggle .mode-moon{display:inline-flex}
html[data-theme=dark] .mode-sun{display:inline-flex}
html[data-theme=dark] .mode-moon{display:none}
.portal-header .nav-shell{position:relative;top:auto;z-index:auto}
.portal-header .nav-inner{min-height:50px;justify-content:flex-start}
.portal-header .main-menu{display:flex;position:static;background:none;box-shadow:none;min-width:0;flex:1}
.portal-header .main-menu>.section{min-width:0;width:100%}
.portal-header .main-menu .widget-content>ul{display:flex;align-items:center;justify-content:flex-start;gap:0;padding:0;margin:0}
.portal-header .main-menu a,.portal-header .main-menu summary{padding:0 17px;line-height:50px;font-size:13px;font-weight:500;letter-spacing:.1px;border:0}
.portal-header .main-menu details>ul a{line-height:43px}
.portal-header .main-menu summary>.mdi{margin-left:5px}
.portal-header .search-panel{top:100%;right:3%;width:390px;z-index:5;border-top:3px solid var(--accent)}
.portal-header .search-panel button{display:grid;place-items:center;min-width:44px;min-height:44px;padding:8px}
.header-ad-strip{background:#fff;padding:20px 0}
.header-ad-strip>.wrap{display:flex;justify-content:center}
.header-ad-strip .header-ad{width:768px;max-width:100%}
.header-ad-strip .ad-slot{margin:0}
.post-cover{max-width:100%;margin:0 0 20px}
.post-cover>.separator{margin:0!important;text-align:left!important}
.post-cover>.separator a{display:block;margin:0!important}
.post-cover img{display:block;width:100%;height:auto;max-height:650px;object-fit:cover;margin:0 auto}
.post-cover p,.post-cover figcaption,.post-cover .tr-caption{margin:8px 0 0;text-align:left!important;font:400 12px/1.6 var(--text);color:#777}
.post-cover table{width:100%;max-width:100%;margin:0!important}
.post-cover table img{max-height:none}
.topbar>.wrap{min-height:36px}
.topbar .social-links{gap:13px}
.topbar .live-link{min-height:36px;font-size:11px}
html[data-theme=dark]{color-scheme:dark;--ink:#f2eeee;--body:#d4cdd0;--line:#393236}
html[data-theme=dark] body{background:#181417;color:var(--body)}
html[data-theme=dark] .portal-header,html[data-theme=dark] .portal-header .masthead,html[data-theme=dark] .header-ad-strip{background:#201a1e}
html[data-theme=dark] .portal-header .icon-button{color:#eee7ea}
html[data-theme=dark] .portal-header .icon-button:hover{background:#3b2b31;color:#ff7582}
html[data-theme=dark] .header-search,html[data-theme=dark] .search-panel input{background:#30272c;border-color:#51434a;color:#f5eff2}
html[data-theme=dark] .header-search button:hover{background:#45343c}
html[data-theme=dark] input::placeholder{color:#b7aab0}
html[data-theme=dark] .header-search button,html[data-theme=dark] .quick-read-link{color:#ff7885}
html[data-theme=dark] .topbar{background:#2a2227;color:#e3d9de}
html[data-theme=dark] .brand-name{color:#f7f1f4}
html[data-theme=dark] .brand-initial{color:#e6bcc2}
html[data-theme=dark] .brand-tagline{color:#c3b5bc}
html[data-theme=dark] .brand-name em{color:#ff6d7b}
html[data-theme=dark] .meta,html[data-theme=dark] .post-cover p,html[data-theme=dark] .post-cover figcaption,html[data-theme=dark] .post-body .tr-caption,html[data-theme=dark] .post-author,html[data-theme=dark] .copyright-row p{color:#b6a7af}
html[data-theme=dark] .categories a{color:color-mix(in srgb,var(--cat,#ff6d7b) 80%,white)}
html[data-theme=dark] .hero .categories a,html[data-theme=dark] .sports .categories a{color:white}
html[data-theme=dark] .site-footer{background:#211b1f;border-color:var(--line)}
html[data-theme=dark] .footer-bottom{background:#2b2228}
html[data-theme=dark] .footer-menu,html[data-theme=dark] .tag-cloud a,html[data-theme=dark] .pager a,html[data-theme=dark] .tabs{border-color:var(--line)}
html[data-theme=dark] .tabs,html[data-theme=dark] .sidebar-tab,html[data-theme=dark] .feed-status,html[data-theme=dark] .empty-state,html[data-theme=dark] .post-body blockquote{background:#2a2227;color:var(--body)}
html[data-theme=dark] .sidebar-tab[aria-selected=true]{background:var(--accent);color:white}
html[data-theme=dark] .sidebar-tabs>.tabs{background:transparent}
html[data-theme=dark] .side-drawer,html[data-theme=dark] .search-panel{background:#241d22;color:var(--body)}
html[data-theme=dark] .search-panel #searchClose{background:#403039;color:white}
html[data-theme=dark] .main-menu details>ul{background:#30242b}
html[data-theme=dark] .main-menu details>ul a{color:#f4eaf0}
html[data-theme=dark] .comment-link strong{color:#f2e7ed}
html[data-theme=dark] .ad-placeholder{color:#bda8b1;border-color:#4b3741;background:repeating-linear-gradient(135deg,#2c2228 0,#2c2228 22px,#31252c 22px,#31252c 44px)}
html[data-theme=dark] .thumb,html[data-theme=dark] .no-photo{background:#31272d;color:#c6b6bf}
html[data-theme=dark] .skip-link{background:#30242b;color:white}
@media(min-width:981px) and (max-width:1200px){
 .header-tools{gap:8px}.header-search{width:300px}.portal-header .main-menu a,.portal-header .main-menu summary{padding:0 12px;font-size:12px}.portal-header .brand-name{font-size:28px}.portal-header .brand-initial{font-size:65px}
}
@media(max-width:980px){
 .portal-header{top:0}
 .portal-header .masthead>.wrap{display:grid;grid-template-columns:48px minmax(0,1fr) 96px;gap:6px;height:66px;min-height:66px;padding:5px 0;align-items:center}
 .portal-header .masthead #spBrand{grid-column:2;grid-row:1;min-width:0;max-width:100%;justify-self:center;text-align:center}
 .portal-header .masthead #spBrand a{display:block}
 .portal-header .brand{max-width:100%}
 .portal-header .brand-initial{font-size:48px;padding-right:10px;letter-spacing:-8px}
 .portal-header .brand-name{font-size:25px;letter-spacing:-1px}
 .portal-header .brand-tagline{font-size:7px;letter-spacing:1.1px;margin-top:5px}
 .portal-header .brand-image{max-height:54px;max-width:100%;width:auto}
 .portal-header .menu-toggle{display:grid;grid-column:1;grid-row:1;margin:0}
 .header-tools{grid-column:3;grid-row:1;display:flex;gap:0;width:96px;margin:0;justify-content:flex-end}
 .header-search,.quick-read-link,.portal-header #drawerToggle{display:none}
 .portal-header .mobile-search{display:grid}
 .portal-header .icon-button{width:48px;height:48px;min-height:48px}
 .portal-header .nav-inner{min-height:44px;width:100%;padding:0 3%;position:relative;gap:0}
 .portal-header .home-link{width:40px;height:44px;flex:none}
 .portal-header .home-link .mdi{width:23px;height:23px}
 .portal-header .main-menu{display:block;position:static;flex:1;min-width:0;overflow-x:auto;overscroll-behavior-inline:contain;scrollbar-width:none;background:transparent;box-shadow:none}
 .portal-header .main-menu::-webkit-scrollbar{display:none}
 .portal-header .main-menu .widget-content>ul{display:flex;flex-wrap:nowrap;align-items:center;gap:0;width:max-content;min-width:100%;padding:0}
 .portal-header .main-menu a,.portal-header .main-menu summary{font-size:12px;line-height:44px;padding:0 13px;border:0}
 .portal-header .main-menu details>ul{position:fixed;top:auto;left:auto;background:var(--secondary);padding:0;min-width:170px;box-shadow:0 8px 20px #0003;z-index:3}
 .portal-header .main-menu details>ul a{color:white;padding:0 16px;font-size:13px}
 .portal-header .main-menu.is-open{position:absolute;top:44px;left:0;right:0;overflow:visible;background:var(--secondary);box-shadow:0 10px 20px #0003;z-index:4;max-height:calc(100dvh - 110px);overflow-y:auto}
 .portal-header .main-menu.is-open .widget-content>ul{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));width:100%;padding:10px 3%}
 .portal-header .main-menu.is-open a,.portal-header .main-menu.is-open summary{font-size:13px;line-height:44px;border-bottom:1px solid #ffffff20;padding:0 15px}
 .portal-header .main-menu.is-open details>ul{position:static;min-width:0;box-shadow:none}
 .portal-header .main-menu.is-open details[open]{grid-column:1/-1}
 .portal-header .main-menu.is-open details>ul a{padding-left:25px}
 .portal-header .search-panel{right:3%;top:100%;max-width:94vw;padding:14px;width:390px}
 .header-ad-strip{padding:15px 0}
 .topbar>.wrap{display:flex;flex-direction:row;flex-wrap:nowrap;align-items:center;justify-content:space-between;gap:10px;padding:0;min-height:32px}
 .topbar .top-details{display:flex;flex:1;min-width:0;font-size:10px;gap:0}
 .topbar .top-links{display:none}
 .topbar>.wrap>.section{display:none;order:0;flex:initial}
 .topbar>.wrap>.top-details{display:flex}
 .topbar .live-link{order:0;min-height:32px;margin:0;padding:0 8px;font-size:10px;white-space:nowrap}
 .post-cover img{max-height:520px}
}
@media(max-width:480px){
 .portal-header .masthead>.wrap{grid-template-columns:44px minmax(0,1fr) 88px;gap:4px;height:62px;min-height:62px}
 .portal-header .icon-button{width:44px;height:48px}
 .header-tools{width:88px}
 .portal-header .brand-initial{font-size:43px;padding-right:8px;letter-spacing:-7px}
 .portal-header .brand-name{font-size:22px}
 .portal-header .brand-tagline{font-size:6px;letter-spacing:.8px}
 .portal-header .brand-image{max-height:48px}
 .portal-header .main-menu a,.portal-header .main-menu summary{padding:0 12px}
 .portal-header .main-menu.is-open{max-height:calc(100dvh - 106px)}
 .header-ad-strip{padding:12px 0}
 .post-cover img{max-height:400px}
}
body#layout .portal-header{position:static!important;top:auto!important}
body#layout .header-tools{display:none!important}
body#layout .portal-header .masthead>.wrap,body#layout .portal-header .main-menu,body#layout .portal-header .main-menu .widget-content>ul{display:block!important;height:auto!important;overflow:visible!important}
body#layout .header-ad-strip>.wrap{display:block!important}

/* SaePaper 1.2.0 — SaeKompi search quick-panel layout; retain SaePaper palette. */
.header-inline-search{position:relative;z-index:125;width:350px;max-width:31vw;flex:0 1 350px}
.header-inline-search .header-search{display:flex;width:100%;max-width:none;min-width:0;height:46px;align-items:center;border-radius:8px;overflow:hidden}
.header-inline-search:focus-within .header-search{border-color:var(--accent);box-shadow:0 0 0 2px color-mix(in srgb,var(--accent) 18%,transparent)}
.header-inline-search .header-search input{height:100%;flex:1;padding:0 8px 0 15px;font-size:13px;line-height:46px}
.header-inline-search .header-search input:focus{outline:0}
.header-inline-search .header-search button{height:46px;width:42px;flex:0 0 42px}
.search-quick-panel{position:absolute;top:calc(100% + 10px);right:0;z-index:130;display:grid;width:min(640px,76vw);grid-template-columns:minmax(0,.9fr) minmax(0,1.15fr);gap:18px;padding:16px;border:1px solid color-mix(in srgb,var(--line) 65%,transparent);border-radius:14px;background:color-mix(in srgb,#fff 74%,transparent);-webkit-backdrop-filter:blur(16px) saturate(140%);backdrop-filter:blur(16px) saturate(140%);box-shadow:0 18px 42px #0000001c;color:var(--body)}
.search-quick-panel[hidden]{display:none!important}
.header-inline-search.is-search-open .search-quick-panel{animation:sp-search-in .16s ease both}
.search-quick-block{min-width:0}
.search-quick-title{display:flex;align-items:center;gap:8px;margin:0 0 10px;color:var(--ink);font-family:var(--heading);font-size:13px;line-height:1.25;font-weight:700}
.search-quick-icon{display:inline-flex;width:28px;height:28px;flex:0 0 28px;align-items:center;justify-content:center;border-radius:50%;background:color-mix(in srgb,var(--accent) 11%,transparent);color:var(--accent)}
.search-quick-icon svg.mdi{display:block;width:15px;height:15px}
.search-quick-tag-list{display:flex;flex-wrap:wrap;gap:7px}
.search-quick-tag-list a{display:inline-flex;min-height:31px;align-items:center;padding:6px 11px;border:1px solid color-mix(in srgb,var(--line) 75%,transparent);border-radius:999px;background:color-mix(in srgb,#fff 65%,transparent);color:var(--ink);font-size:11px;line-height:1.2;font-weight:700;transition:background .15s,border-color .15s,color .15s}
.search-quick-tag-list a:hover{border-color:color-mix(in srgb,var(--accent) 38%,transparent);background:color-mix(in srgb,var(--accent) 9%,transparent);color:var(--accent)}
.search-quick-post-list{display:grid;gap:7px}
.search-quick-post{display:grid;grid-template-columns:58px minmax(0,1fr);gap:9px;align-items:center;padding:5px;border-radius:9px;color:inherit;transition:background .15s}
.search-quick-post:hover{background:color-mix(in srgb,#fff 62%,transparent);color:inherit}
.search-quick-thumb{display:block;width:58px;height:44px;overflow:hidden;border-radius:7px;background:#e9e2e4}
.search-quick-thumb img{display:block;width:100%;height:100%;object-fit:cover}
.search-quick-post-copy{min-width:0}
.search-quick-post-copy strong{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;color:var(--ink);font-family:var(--heading);font-size:11px;line-height:1.35;font-weight:700}
.search-quick-post-copy small{display:block;margin-top:3px;overflow:hidden;color:#777;font-size:9px;line-height:1.3;text-overflow:ellipsis;white-space:nowrap}
.search-quick-status{margin:8px 0;color:#777;font-size:12px;line-height:1.5}
.search-quick-retry{justify-self:start;padding:7px 11px;border:1px solid var(--line);border-radius:6px;color:var(--accent);font-size:12px}
.portal-header #searchPanel.search-panel{display:none}
html[data-theme=dark] .search-quick-panel{background:color-mix(in srgb,#241d22 90%,transparent);border-color:var(--line);color:var(--body)}
html[data-theme=dark] .search-quick-tag-list a{background:#30252c;border-color:#57444d;color:var(--ink)}
html[data-theme=dark] .search-quick-tag-list a:hover{background:#4a2c37;color:#ff8996;border-color:#94616f}
html[data-theme=dark] .search-quick-post:hover{background:#ffffff0f}
html[data-theme=dark] .search-quick-thumb{background:#3a2b33}
html[data-theme=dark] .search-quick-post-copy small,html[data-theme=dark] .search-quick-status{color:#bbadb4}
@keyframes sp-search-in{from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:none}}
@media(min-width:981px) and (max-width:1200px){.header-inline-search{width:300px;flex-basis:300px}}
@media(max-width:980px){
 .header-inline-search{display:none}
 .portal-header #searchPanel.search-panel:not([hidden]){position:relative;display:block;top:auto;right:auto;z-index:140;width:100%;max-width:none;margin:0;padding:8px 3% 12px;border:0;background:#fff;box-shadow:none;color:var(--body)}
 .portal-header #searchPanel form{display:flex;height:44px;align-items:center;padding:0;border:1px solid #dedede;border-radius:9px;background:#f7f7f7;overflow:hidden}
 .portal-header #searchPanel input{min-width:0;flex:1;height:44px;padding:0 10px 0 14px;border:0;outline:0;background:transparent;color:var(--ink);font-size:14px;box-shadow:none}
 .portal-header #searchPanel input:focus{outline:0}
 .portal-header #searchPanel form:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px color-mix(in srgb,var(--accent) 18%,transparent)}
 .portal-header #searchPanel form>button{display:grid;width:44px;height:44px;min-height:44px;flex:0 0 44px;place-items:center;padding:0;border:0;background:transparent;color:var(--accent)}
 .portal-header #searchPanel #searchClose{margin:0;background:transparent;color:#666;border-left:1px solid var(--line)}
 .portal-header #searchPanel form svg.mdi{pointer-events:none;width:20px;height:20px}
 .portal-header #searchPanel .search-quick-panel{position:static;display:grid;width:100%;grid-template-columns:1fr;gap:14px;margin-top:8px;padding:14px;border-radius:12px;max-height:min(62vh,520px);max-height:min(62dvh,520px);overflow:auto;overscroll-behavior:contain;animation:sp-search-in .16s ease both}
 .portal-header #searchPanel .search-quick-tag-list{flex-wrap:nowrap;overflow-x:auto;padding-bottom:2px;scrollbar-width:none;-webkit-overflow-scrolling:touch}
 .portal-header #searchPanel .search-quick-tag-list::-webkit-scrollbar{display:none}
 .portal-header #searchPanel .search-quick-tag-list a{flex:0 0 auto}
 .portal-header #searchPanel .search-quick-post{min-height:54px}
 .portal-header #searchPanel .search-quick-post-copy strong{font-size:12px}
 .portal-header #searchPanel .search-quick-tag-list a{min-height:36px}
 html[data-theme=dark] .portal-header #searchPanel.search-panel{background:#201a1e}
 html[data-theme=dark] .portal-header #searchPanel form{background:#30272c;border-color:#51434a}
 html[data-theme=dark] .portal-header #searchPanel #searchClose{color:#d8c8d0;border-color:#51434a}
 body.mobile-search-open .header-ad-strip,body.mobile-search-open .sp-ad-leader{display:none}
}
@media(prefers-reduced-motion:reduce){.search-quick-panel,.search-quick-tag-list a,.search-quick-post{animation:none!important;transition:none!important}}
body#layout .header-inline-search,body#layout #searchPanel{display:none!important}

/* SaePaper 1.2.0: iPlus complete advertising geometry, audited 27 October 2026. */
.sp-ad-unit{display:block;position:relative;clear:both;margin:30px auto;text-align:center;max-width:100%;min-width:0}
.sp-ad-unit .section,.sp-ad-unit .widget,.sp-ad-unit .widget-content{margin:0;padding:0;min-width:0}
.sp-ad-placeholder{display:flex;position:relative;align-items:center;justify-content:center;max-width:100%;margin:0 auto;background:#e1e0e0;color:#999;line-height:1}
.sp-ad-placeholder>span{padding:3px;border-radius:3px;background:#666;color:#fff;font:bold 10px/1 Arial,sans-serif}
.sp-ad-970{width:970px;height:250px}.sp-ad-728{width:728px;height:90px}.sp-ad-300{width:300px;height:300px}.sp-ad-600{width:300px;height:600px}.sp-ad-160{width:160px;height:600px}
.sp-ad-unit img,.sp-ad-unit iframe,.sp-ad-unit ins{max-width:100%}
.sp-ad-top{position:relative;margin:0;height:250px;clip-path:inset(0);overflow:hidden;background:#0d0d0d;z-index:0}
.sp-ad-top-layer{position:fixed;top:0;left:50%;width:970px;max-width:100%;transform:translateX(-50%);line-height:0}
.sp-ad-top .sp-ad-placeholder{width:970px;height:250px}
.sp-ad-top-caption{display:none}
.sp-ad-rail{position:fixed;top:110px;width:160px;height:min(600px,calc(100dvh - 110px));max-height:600px;overflow:hidden;z-index:20;display:none;margin:0}
.sp-ad-rail-left{right:calc(50% + var(--sp-ad-wrap,var(--wrap))/2 + 20px)}
.sp-ad-rail-right{left:calc(50% + var(--sp-ad-wrap,var(--wrap))/2 + 20px)}
.sp-ad-rail .sp-ad-placeholder{width:160px;height:600px}
.sp-ad-bottom{position:fixed;bottom:0;left:50%;transform:translateX(-50%);z-index:95;width:728px;max-width:100%;height:90px;margin:0;text-align:center;background:#fff}
.sp-ad-bottom .sp-ad-placeholder{width:728px;max-width:100%;height:90px}
.sp-ad-close{position:absolute;top:-24px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:5px;padding:2px 3px 2px 10px;border-radius:20px;background:var(--accent);color:#fff;font:700 10px/17px Arial,sans-serif;z-index:2}
.sp-ad-close .mdi{display:block;width:17px;height:17px;padding:1px;border-radius:50%;background:#ddd;color:#111}
body.sp-has-sticky-ad{padding-bottom:110px}
body.sp-has-sticky-ad .back-top{bottom:110px}
.sp-article-parallax{display:block;clear:both;margin:25px 0;background:#0d0d0d;color:white;font:10px/15px Arial,sans-serif}
.sp-article-parallax .sp-px{position:relative;height:300px;clip-path:inset(0);overflow:hidden;background:#0d0d0d}
.sp-article-parallax .sp-px-layer{position:fixed;top:50%;left:var(--sp-ad-center,50%);transform:translate(-50%,-50%);width:300px;max-width:var(--sp-ad-width,calc(100vw - 20px));line-height:0}
.sp-article-parallax .sp-ad-placeholder{width:300px;height:600px;max-width:100%}
.sp-article-parallax .widget,.sp-article-parallax .section,.sp-article-parallax .widget-content{margin:0;padding:0}
.sp-parallax-caption{height:15px;text-align:center;text-transform:uppercase;background:#222;color:#fff;font:9px/15px Arial,sans-serif;letter-spacing:.1px}
.sp-ad-sidebar-end{margin-bottom:0}
@media(min-width:1024px){
 .page-grid{grid-template-columns:340px minmax(0,1fr)}
 .page-grid>.sidebar{align-self:stretch}
 .sidebar>.sp-ad-sidebar-end{position:sticky;top:var(--sp-sidebar-ad-top,62px)}
}
@media(min-width:1400px){
 :root{--sp-ad-wrap:min(1366px,calc(100vw - 408px))}
 .wrap{width:var(--sp-ad-wrap);max-width:1366px}
 .page-grid{grid-template-columns:340px minmax(0,1fr)}
 .sp-ad-rail{display:block}
 .hero.sp-feed{width:var(--sp-ad-wrap);max-width:1366px;margin-left:auto;margin-right:auto}
}
@media(max-width:768px){
 .sp-ad-top{height:600px;background:#111}
 .sp-ad-top-layer{width:300px;max-width:100%}
 .sp-ad-top .sp-ad-placeholder{width:300px;height:585px}
 .sp-ad-top-caption{position:absolute;bottom:0;left:0;display:block;width:100%;height:15px;text-align:center;background:#222;color:#fff;font:10px/15px var(--text);text-transform:uppercase}
 .sp-ad-unit{margin:15px auto}
 .sp-ad-top,.sp-ad-bottom,.sp-ad-rail{margin:0}
 .sp-ad-bottom{display:block;width:100%;height:90px}
 .sp-ad-bottom .sp-ad-placeholder{width:100%;height:90px}
 .sidebar .sp-ad-unit .sp-ad-placeholder{width:100%}
 .sp-article-parallax{width:var(--sp-article-viewport,100%);margin:20px 0 20px var(--sp-article-outset,0px)}
 .sidebar>.sp-ad-sidebar-end{position:static}
}
html[data-theme=dark] .sp-ad-placeholder{background:#303030;color:#999}
html[data-theme=dark] .sp-ad-bottom{background:#181417}
body#layout .sp-ad-unit,body#layout .sp-ad-top,body#layout .sp-ad-top-layer,body#layout .sp-ad-rail,body#layout .sp-ad-bottom,body#layout .sp-article-ad-holder,body#layout .sp-article-parallax,body#layout .sp-px,body#layout .sp-px-layer{display:block!important;position:static!important;inset:auto!important;transform:none!important;width:auto!important;height:auto!important;max-height:none!important;max-width:none!important;overflow:visible!important;clip-path:none!important;margin:12px 0!important;background:#fff!important}
body#layout .sp-ad-close,body#layout .sp-ad-top-caption,body#layout .sp-parallax-caption{display:none!important}
body#layout .sp-ad-placeholder{display:none!important}
body#layout.sp-has-sticky-ad{padding-bottom:0}

.sp-native-labels{display:none}

.sp-footer-plain{white-space:pre-line}

.tbd-license-gate[hidden],.tbd-license-shield[hidden],.tbd-license-status[hidden],#tbd-license-context[hidden]{display:none!important}
.tbd-license-gate,.tbd-license-gate *,.tbd-license-status,.tbd-license-status *{box-sizing:border-box}
.tbd-license-gate{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;overflow:auto;padding:24px 16px;background:rgba(15,23,42,.55);font-family:Arial,system-ui,sans-serif;color:#172339;text-align:left;line-height:1.6}
.tbd-license-card{width:100%;max-width:460px;margin:auto;padding:30px;background:#fff;border:1px solid #e5eaf2;border-radius:22px;box-shadow:0 24px 80px #0f172a40}
.tbd-license-brand{display:inline-flex;align-items:center;gap:8px;color:#172339!important;text-decoration:none!important;font:bold 21px/1.3 Arial,sans-serif;letter-spacing:-.6px}
.tbd-license-brand b{color:#2456d9}.tbd-license-logo{position:relative;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;color:#fff;background:#2456d9;font:bold 24px/1 Arial,sans-serif;letter-spacing:0}.tbd-license-logo>span{position:absolute;right:5px;bottom:5px;width:6px;height:6px;border-radius:50%;background:#ffb300}
.tbd-license-symbol{display:grid;place-items:center;width:54px;height:54px;margin-top:28px;margin-bottom:16px;border-radius:15px;background:#edf2ff;color:#2456d9}
.tbd-license-eyebrow{margin:0 0 8px!important;color:#526178;font:bold 11px/1.5 Arial,sans-serif;letter-spacing:1.3px}
.tbd-license-card h2{margin:0 0 14px!important;padding:0;color:#172339;font:bold 26px/1.25 Arial,sans-serif;letter-spacing:-.7px;overflow-wrap:anywhere}
.tbd-license-card #tbd-license-description{margin:0 0 24px!important;color:#526178;font:15px/1.7 Arial,sans-serif;overflow-wrap:anywhere}
.tbd-license-card strong{color:#172339;font-weight:700}
.tbd-license-actions{display:grid;gap:10px}
.tbd-license-actions a{display:flex;justify-content:center;align-items:center;min-height:48px;padding:12px 16px;border:1px solid #2456d9;border-radius:11px;background:#2456d9;color:#fff!important;text-decoration:none!important;font:bold 15px/1.45 Arial,sans-serif;text-align:center;overflow-wrap:anywhere}
.tbd-license-actions a:hover{background:#173fa9;border-color:#173fa9}.tbd-license-actions .tbd-license-secondary{background:#fff;color:#2456d9!important;border-color:#d3ddef}.tbd-license-actions .tbd-license-secondary:hover{background:#f5f7fb}
#tbd-license-check{display:block;margin:18px auto 0;padding:6px 3px;border:0;background:transparent;color:#526178;font:14px/1.5 Arial,sans-serif;text-align:center;text-decoration:underline;text-underline-offset:4px;cursor:pointer}
.tbd-license-gate :focus-visible,.tbd-license-status button:focus-visible{outline:3px solid #9db5ff;outline-offset:3px}
.tbd-license-modal{overflow:hidden}.tbd-license-shield{position:fixed;inset:0;z-index:2147482000;background:transparent}
.tbd-license-status{position:fixed;z-index:2147483001;left:50%;bottom:18px;transform:translateX(-50%);width:calc(100% - 32px);max-width:440px;padding:16px 18px;border:1px solid #e5eaf2;border-radius:12px;background:#fff;color:#526178;box-shadow:0 6px 30px #0f172a20;font:14px/1.6 Arial,sans-serif}
.tbd-license-status button{display:block;margin-top:8px;padding:7px 12px;border:0;border-radius:8px;background:#2456d9;color:#fff;font:bold 13px/1.5 Arial,sans-serif;cursor:pointer}
@media(max-width:380px){.tbd-license-card{padding:24px 20px}.tbd-license-card h2{font-size:23px}}


/* Native license input is invisible on the public site. */
.tb-license-settings{display:none!important}

head.b:template-skin:
/* TemaBlogger License Key: native Layout controls remain editable. */
body#layout .tb-license-settings{display:block!important;width:auto!important;clear:both!important;margin:0 0 16px!important;padding:12px!important;border:1px solid #d8e3f5!important;border-radius:12px!important;background:#f0f5ff!important}
body#layout .tb-license-settings .add_widget{display:none!important}

/* SaePaper 1.3.1: native Blogger Layout only. Public pages are unaffected. */
.sp-layout-wrap{display:contents}
body#layout{margin:0!important;padding:18px!important;box-sizing:border-box;background:#f3f5f8!important;color:#293443!important;font:13px/1.45 Arial,sans-serif!important;min-width:0!important}
body#layout *,body#layout *:before,body#layout *:after{box-sizing:border-box}
body#layout .wrap{display:block!important;width:auto!important;max-width:none!important;height:auto!important;min-height:0!important;max-height:none!important;float:none!important;clear:both!important;margin:0!important;padding:0!important}
body#layout .home-only,body#layout .interior-only,body#layout .blog-section,body#layout .drawer-source,body#layout .sidebar-panel{display:block!important}
body#layout .breaking,body#layout .topbar,body#layout .top-details,body#layout .masthead,body#layout .portal-header,body#layout .nav-shell,body#layout .nav-inner,body#layout .main-menu,body#layout .highlights-band,body#layout .site-footer,body#layout .footer-bottom,body#layout .copyright-row,body#layout .sidebar-tabs,body#layout .paired-blocks{position:static!important;display:block!important;inset:auto!important;width:auto!important;min-height:0!important;height:auto!important;max-height:none!important;margin:0!important;padding:0!important;overflow:visible!important;clip-path:none!important;transform:none!important;background:transparent!important;border:0!important;box-shadow:none!important;color:inherit!important}
body#layout .masthead>.wrap{height:auto!important;min-height:0!important;display:block!important;padding:0!important}
body#layout .sp-ad-unit,body#layout .sp-ad-top,body#layout .sp-ad-top-layer,body#layout .sp-ad-rail,body#layout .sp-ad-bottom,body#layout .sp-article-ad-holder,body#layout .sp-article-parallax,body#layout .sp-px,body#layout .sp-px-layer{display:block!important;position:static!important;inset:auto!important;transform:none!important;width:auto!important;min-height:0!important;height:auto!important;max-height:none!important;max-width:none!important;overflow:visible!important;clip-path:none!important;margin:0!important;padding:0!important;background:transparent!important;text-align:left!important;clear:none!important}
body#layout .section{display:block!important;position:relative!important;float:none!important;width:auto!important;min-width:0!important;min-height:0!important;margin:0 0 12px!important;padding:12px!important;border:1px solid #dbe1e8!important;border-radius:9px!important;background:#fff!important;box-shadow:0 1px 2px #1c2e4610!important;overflow:visible!important;color:#293443!important}
body#layout .section h4,body#layout .section .section-title{margin:0 0 9px!important;padding:0!important;font:700 11px/1.4 Arial,sans-serif!important;letter-spacing:.15px!important;color:#586779!important;overflow-wrap:anywhere}
body#layout .widget{position:relative!important;float:none!important;width:auto!important;min-width:0!important;min-height:66px!important;height:auto!important;max-height:none!important;margin:0!important;padding:0!important;overflow:visible!important;background:#f7f9fc!important;color:#293443!important;box-shadow:none!important;border-radius:6px!important}
body#layout .widget .widget-wrap1,body#layout .widget .widget-wrap2,body#layout .widget .widget-wrap3{min-width:0!important;max-width:100%!important;height:auto!important;min-height:0!important;overflow:visible!important;background:transparent!important}
body#layout .widget .widget-content{display:block!important;position:relative!important;min-width:0!important;min-height:66px!important;height:auto!important;overflow:visible!important;font:12px/1.5 Arial,sans-serif!important;color:#293443!important}
body#layout .widget .widget-content{padding:13px 48px 12px 12px!important}
body#layout .layout-title{width:auto!important;max-width:none!important;height:auto!important;text-overflow:clip!important;margin:0 0 5px 31px!important;font:700 13px/1.4 Arial,sans-serif!important;white-space:normal!important;overflow-wrap:anywhere}
body#layout .layout-widget-description{margin-left:31px!important;font:11px/1.4 Arial,sans-serif!important;color:#798597!important}
body#layout .layout-widget-state{position:absolute!important;left:12px!important;top:18px!important}
body#layout .widget .editlink{position:absolute!important;right:9px!important;top:15px!important;width:auto!important;text-indent:0!important;background-image:none!important}
body#layout .widget h3{margin:0 60px 6px 0!important;font:700 13px/1.4 Arial,sans-serif!important;color:#26364b!important;overflow-wrap:anywhere}
body#layout .widget p{margin:0!important;font:11px/1.5 Arial,sans-serif!important;color:#7b8795!important}
body#layout .editlink{display:inline-flex!important;align-items:center;justify-content:center;visibility:visible!important;opacity:1!important;min-width:36px!important;min-height:28px!important;padding:4px 7px!important;border-radius:5px!important;background:#e8f0fd!important;color:#275dab!important;font:700 11px/1.4 Arial,sans-serif!important;text-decoration:none!important;z-index:5!important;pointer-events:auto!important}
body#layout .editlink:hover,body#layout .editlink:focus{background:#d8e7fb!important;color:#174d98!important;outline:2px solid #84afea!important;outline-offset:2px!important}
body#layout .layout-widget-state{visibility:visible!important;opacity:1!important;z-index:5!important;pointer-events:auto!important}
body#layout .add_widget{visibility:visible!important;opacity:1!important;padding:5px 0!important;color:#547293!important;font:11px/1.4 Arial,sans-serif!important}
body#layout .section.no-items{min-height:72px!important;border-style:dashed!important}
body#layout .sp-layout-group{display:block!important;position:relative!important;margin:0 0 18px!important;padding:14px!important;border:1px solid #d5dde7!important;border-radius:11px!important;background:#eaf0f6!important;min-width:0!important}
body#layout .sp-layout-group:before{content:attr(data-layout-title);display:block!important;margin:0 0 13px!important;padding:0 0 10px!important;border-bottom:1px solid #ccd8e5!important;color:#304d70!important;font:700 14px/1.4 Arial,sans-serif!important;letter-spacing:.15px}
body#layout .sp-layout-group:empty{display:none!important}
body#layout .sp-layout-top:before{content:'01 - Iklan Atas dan Samping'}
body#layout .sp-layout-header:before{content:'02 - Header dan Navigasi'}
body#layout .sp-layout-home-top:before{content:'03 - Headline dan Sorotan'}
body#layout .sp-layout-main:before{content:'04 - Konten Utama'}
body#layout .sp-layout-sidebar:before{content:'05 - Sidebar'}
body#layout .sp-layout-article:before{content:'Halaman Artikel'}
body#layout .sp-layout-bottom:before{content:'06 - Slider Berita Bawah'}
body#layout .sp-layout-footer:before{content:'07 - Footer'}
body#layout .sp-layout-floating:before{content:'08 - Iklan Melayang Bawah'}
body#layout .sp-layout-group>.section:last-child,body#layout .sp-layout-group>.sp-ad-unit:last-child>.section{margin-bottom:0!important}
body#layout .page-grid{display:block!important;width:auto!important;max-width:none!important;margin:0 0 18px!important;padding:0!important}
body#layout .page-grid:after{content:'';display:block;clear:both}
body#layout .main-column{display:block!important;float:left!important;width:66%!important;min-width:0!important;margin:0!important;padding:0!important}
body#layout .sidebar{display:block!important;float:right!important;width:29%!important;min-width:0!important;margin:0!important;padding:0!important}
body#layout .page-grid>.sp-layout-group{margin-bottom:0!important;padding:14px!important}
body#layout .footer-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:12px!important;width:auto!important;max-width:none!important;margin:0!important;padding:0!important}
body#layout .footer-grid>.section,body#layout .footer-grid>.sp-ad-unit{min-width:0!important;margin:0!important}
body#layout .footer-grid>div:not(.section){display:block!important;margin:0!important;padding:0!important;min-width:0!important}
body#layout .breaking-label,body#layout #today,body#layout .live-link,body#layout .brand,body#layout .brand-image,body#layout .drawer-brand,body#layout .drawer-about,body#layout .header-tools,body#layout .icon-button,body#layout .home-link,body#layout .skip-link,body#layout #sideDrawer,body#layout #searchPanel,body#layout .header-inline-search,body#layout .search-quick-panel,body#layout .sp-ad-placeholder,body#layout .ad-placeholder,body#layout .ad-caption,body#layout .sp-ad-close,body#layout .sp-ad-top-caption,body#layout .sp-parallax-caption,body#layout .back-top,body#layout .tabs,body#layout .feed-status,body#layout .feed-retry,body#layout .carousel-prev,body#layout .carousel-next,body#layout .carousel-dots,body#layout .sp-config,body#layout .recent-comments,body#layout .sr-only{display:none!important}
body#layout .footer-grid>div>h2,body#layout .copyright-row>p{display:none!important}
body#layout .sp-layout-top .section,body#layout .sp-layout-floating .section{border-left:3px solid #bd4c5d!important}
body#layout .sp-layout-header .section{border-left:3px solid #4c81b9!important}
body#layout .sp-layout-home-top .section,body#layout .sp-layout-main .section{border-left:3px solid #588d74!important}
body#layout .sp-layout-sidebar .section{border-left:3px solid #8a76af!important}
body#layout .sp-layout-article .section{border-left:3px solid #b58a4e!important}
body#layout .sp-layout-footer .section{border-left:3px solid #647b8d!important}
@media(max-width:720px){
 body#layout{padding:10px!important}
 body#layout .page-grid{display:block!important}
 body#layout .main-column,body#layout .sidebar{float:none!important;width:auto!important;margin-bottom:16px!important}
 body#layout .sp-layout-group{padding:10px!important}
 body#layout .footer-grid{grid-template-columns:1fr!important}
}
